"""Extract pinned BWAPI4.4.0/OpenBW Spawn Broodlings and summoned unit facts."""
import re,json,hashlib,sys
from pathlib import Path
root=Path(sys.argv[1] if len(sys.argv)>1 else 'work/sources')
u=(root/'unit.cpp').read_text();t=(root/'tech.cpp').read_text();w=(root/'weapon.cpp').read_text();e=(root/'bwgame.h').read_text()
def body(s,n):return re.search(re.escape(n)+r'\[[^\]]+\]\s*=\s*\{(.*?)\};',re.sub(r'//[^\n]*','',s),re.S)[1]
def nums(s,n):return [float(x)for x in re.findall(r'-?\d+(?:\.\d+)?',body(s,n))]
def words(s,n):return re.findall(r'\b[A-Za-z_][A-Za-z_0-9]*\b',body(s,n))
def names(s):return re.findall(r'"([^"]*)"',body(s,'typeNames'))
un=names(u);tn=names(t);wn=names(w);dims=[[int(x)for x in re.findall(r'\d+',v)]for v in re.findall(r'\{([^{}]+)\}',body(u,'unitDimensions'))];flags=body(u,'unitFlags').split(',');i=un.index('Zerg_Broodling');values={k:nums(u,k)[i]for k in ['defaultOreCost','defaultGasCost','defaultTimeCost','defaultMaxHP','defaultMaxSP','defaultArmorAmount','unitSupplyProvided','unitSupplyRequired','unitTopSpeeds','sightRangeTiles']};values={k:int(v)if v.is_integer()else v for k,v in values.items()};unit={'name':'Zerg_Broodling','bwapiId':i,**values,'dimensions':dims[i]};profile={'name':unit['name'],'size':words(u,'unitSize')[i].lower(),'bounds':dims[i][2:],'groundWeapon':words(u,'groundWeapon')[i],'airWeapon':words(u,'airWeapon')[i],'hits':int(nums(u,'groundWeaponHits')[i])};j=wn.index(profile['groundWeapon']);weapon={'name':wn[j],'bwapiId':j,**{k:int(nums(w,k)[j])for k in ['defaultWpnDamageAmt','defaultWpnDamageBonus','wpnDamageCooldowns','wpnDamageFactor','wpnMinRange','wpnMaxRange']},'damageType':words(w,'damageType')[j],'upgrade':words(w,'upgrade')[j]};traits={'name':unit['name'],'spaceRequired':int(nums(u,'unitSpaceRequired')[i]),'spaceProvided':int(nums(u,'unitSpaceProvided')[i]),'flyer':'Flyer'in flags[i],'detector':False,'permanentCloak':False};k=tn.index('Spawn_Broodlings');q=wn.index('Spawn_Broodlings');targetFlags=[v.strip()for v in body(w,'wpnFlags').split(',')[q].split('|')];assert targetFlags==['TARG_GROUND','TARG_NOBUILD','TARG_NOROBOT','TARG_ORGMECH']
tech={'name':'Spawn_Broodlings','id':'spawn-broodlings','title':'브루들링 생성','producer':words(t,'whatResearches')[k].lower().replace('_','-'),'minerals':int(nums(t,'defaultOreCost')[k]),'gas':int(nums(t,'defaultOreCost')[k]),'frames':int(nums(t,'defaultTimeCost')[k]),'energy':int(nums(t,'defaultEnergyCost')[k]),'rangePixels':int(nums(w,'wpnMaxRange')[q]),'targetFlags':targetFlags}
assert 'if (unit_is(u, UnitTypes::Zerg_Broodling)) return 1800;'in e and 'u->remove_timer != 0 && --u->remove_timer == 0'in e;area=e[e.index('void spawn_broodlings'):e.index('void ensnare_unit')];assert 'spawn(target->sprite->position - xy(2, 2))'in area and 'spawn(target->sprite->position + xy(2, 2))'in area and 'kill_unit(target)'in area
out={'source':{'bwapiTag':'v4.4.0','openbwCommit':json.loads((root/'openbw-commit.json').read_text())['sha'],'sha256':{n:hashlib.sha256((root/n).read_bytes()).hexdigest()for n in ['unit.cpp','tech.cpp','weapon.cpp','bwgame.h']}},'units':[unit],'profiles':[profile],'weapons':[weapon],'traits':[traits],'technology':tech,'lifetimeFrames':1800,'count':2,'targetableUnits':[un[n]for n,f in enumerate(flags)if ('OrganicUnit'in f or 'Mechanical'in f)and 'RoboticUnit'not in f and 'Building'not in f and 'Flyer'not in f]}
Path('app/stark-rift/data/broodlings-original.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'unit':unit,'weapon':weapon,'technology':tech},ensure_ascii=False))
